{
  "title": "The Glass Diver's Rescue",
  "scenes": [
    {
      "scene_number": 1,
      "caption": "Mara unfolds her map at the edge of the ruined city.",
      "visual_description": "A weary mapmaker crouches on a cracked cobblestone road at dusk, spreading a hand-drawn map weighted with a brass compass. Broken spires and torn banners loom on the horizon.",
      "characters": ["mara_the_cartographer"]
    },
    {
      "scene_number": 2,
      "caption": "The oracle lamp flickers awake with a warning.",
      "visual_description": "Close-up of an oil lamp held in gloved hands, a single glowing eye blinking inside its flame, casting long nervous shadows across Mara's ink-stained sleeve.",
      "characters": ["mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 3,
      "caption": "Tin Fox sniffs out a hidden path through the rubble.",
      "visual_description": "A small clockwork fox with blue glass eyes and a key-wound tail leaps across fallen masonry, leaving tiny brass paw prints in the ash.",
      "characters": ["tin_fox", "mara_the_cartographer"]
    },
    {
      "scene_number": 4,
      "caption": "The Glass Diver emerges from a shattered window.",
      "visual_description": "A figure in a clear diving helmet slides headfirst through a cracked stained-glass pane as if it were water, coat rippling with reflections of broken city lights.",
      "characters": ["glass_diver"]
    },
    {
      "scene_number": 5,
      "caption": "The team gathers beneath the looming castle gates.",
      "visual_description": "Four companions stand in the shadow of immense iron gates carved with faded royal sigils. The lamp's eye glows wary; the fox crouches; Mara points; the diver studies a mirrored panel.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 6,
      "caption": "They find the tax collector snoring at his post.",
      "visual_description": "Inside a dusty gatehouse, a plump official sleeps face-down on a ledger pillow, stamped papers stuck to his sleeves, drool pooling on a writ of passage.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer"]
    },
    {
      "scene_number": 7,
      "caption": "Tin Fox steals the seal ring from the dozer's finger.",
      "visual_description": "The clockwork fox delicately tugs a brass signet ring off a snoring hand, ears perked, blue eyes gleaming in lamplight.",
      "characters": ["tin_fox", "sleeping_tax_collector", "oracle_lamp"]
    },
    {
      "scene_number": 8,
      "caption": "The oracle lamp warns of the cursed tower ahead.",
      "visual_description": "On a moonlit plaza, the lamp's flame-eye widens, projecting a ghostly silhouette of a leaning tower onto a wall of peeling royal banners.",
      "characters": ["oracle_lamp", "mara_the_cartographer", "glass_diver"]
    },
    {
      "scene_number": 9,
      "caption": "Mara charts a route around the rumored beast's lair.",
      "visual_description": "Mara kneels by a smoking crater, sketching scaled tracks into her map while distant roars echo. Her compass needle spins wildly.",
      "characters": ["mara_the_cartographer", "tin_fox"]
    },
    {
      "scene_number": 10,
      "caption": "Frightened faces peer from boarded windows.",
      "visual_description": "Pale, hollow-eyed townsfolk peek through shutter slats as the diver passes below, his reflective coat splashing their hidden faces with shards of light.",
      "characters": ["glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 11,
      "caption": "An armored patrol marches across the square.",
      "visual_description": "From behind a toppled fountain, the companions watch lantern-lit figures in plate armor stomp past in formation, their banners frayed and crowned with rust.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 12,
      "caption": "The Glass Diver slips through a mirror to scout ahead.",
      "visual_description": "A tall cracked mirror ripples like water as the diver plunges in shoulder-first, his helmet shining with refracted torchlight from the other side.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 13,
      "caption": "They reach the sealed magic door of the keep.",
      "visual_description": "An arched door inlaid with shifting silver runes pulses faintly. Mara presses her compass to it; the lamp leans close; the fox sniffs the threshold.",
      "characters": ["mara_the_cartographer", "oracle_lamp", "tin_fox"]
    },
    {
      "scene_number": 14,
      "caption": "Tin Fox's key-tail unlocks the rune-bound lock.",
      "visual_description": "The fox's wound tail clicks into a hidden keyhole; runes flare blue, swirling around its little metal body as the door groans open.",
      "characters": ["tin_fox", "mara_the_cartographer", "oracle_lamp"]
    },
    {
      "scene_number": 15,
      "caption": "Inside, they find the captive bound in glass chains.",
      "visual_description": "A figure hangs suspended in a vaulted hall, wrists wrapped in translucent shimmering chains. The Glass Diver steps out from a tall windowpane to free them.",
      "characters": ["glass_diver", "mara_the_cartographer"]
    },
    {
      "scene_number": 16,
      "caption": "The tax collector awakens and demands a toll.",
      "visual_description": "Mid-flight through a corridor, the dozing official stumbles after them waving a stamp, papers fluttering, half-asleep eyes squinting under his ledger-pillow.",
      "characters": ["sleeping_tax_collector", "mara_the_cartographer", "tin_fox", "glass_diver", "oracle_lamp"]
    },
    {
      "scene_number": 17,
      "caption": "The companions sprint onto the long stone bridge.",
      "visual_description": "A windswept arched bridge over a black chasm; torn royal banners snap overhead as the four companions race across, the lamp's eye blazing like a tiny sun.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    },
    {
      "scene_number": 18,
      "caption": "Safe on the far shore, Mara folds the map closed.",
      "visual_description": "Dawn breaks over rolling hills beyond the ruined city. Mara smiles tiredly, the fox curled at her boots, the diver gazing back at the smoking skyline, the lamp dimming to a soft glow.",
      "characters": ["mara_the_cartographer", "glass_diver", "tin_fox", "oracle_lamp"]
    }
  ]
}

